script:
if doc.comment_type == "Comment" and doc.reference_doctype == "ToDo":
    content = doc.content or ""
    mentions = []
    start = 0

    while True:
        key = 'data-id="'
        id_index = content.find(key, start)
        if id_index == -1:
            break

        start_quote = id_index + len(key)
        end_quote = content.find('"', start_quote)
        if end_quote == -1:
            break

        user_id = content[start_quote:end_quote].strip()
        if user_id and user_id not in mentions:
            mentions.append(user_id)

        start = end_quote + 1

    # Load the referenced ToDo document
    todo = frappe.get_doc("ToDo", doc.reference_name)

    for user_id in mentions:
        # Skip if same as the ToDo owner
        if user_id == todo.owner:
            continue

        if frappe.db.exists("User", user_id):
            user_doc = frappe.get_doc("User", user_id)

            # Skip if user is disabled or Administrator
            if user_doc.enabled and user_id.lower() != "administrator":
                exists = frappe.db.exists("DocShare", {
                    "share_doctype": doc.reference_doctype,
                    "share_name": doc.reference_name,
                    "user": user_id
                })

                if not exists:
                    new_share = frappe.get_doc({
                        "doctype": "DocShare",
                        "user": user_id,
                        "share_doctype": doc.reference_doctype,
                        "share_name": doc.reference_name,
                        "read": 1,
                        "write": 0,
                        "share": 1
                    })
                    new_share.insert(ignore_permissions=True)

# Trigger: Before Save on Task
if doc.subject:
    try:
        # Fetch the personnel, days, and hours values from the child table of the Task
        task_personnel_data = []
        for row in doc.custom_time_allocation:
            task_personnel_data.append({
                'personnel': row.personnel,
                'days': row.days,
                'hours': row.hours  # Extract hours from the child table
            })

        # Check if there are Task Time Distribution records related to this task
        task_time_distribution = frappe.db.sql("""
            SELECT name, personnel, days_allocated, hours_allocated
            FROM `tabTask Time Distribution`
            WHERE project_task = %s
        """, (doc.name), as_dict=True)

        # For each Task Time Distribution record, check if the personnel matches and update days_allocated & hours_allocated
        for task_person in task_personnel_data:
            # Check if this personnel exists in Task Time Distribution
            matching_distribution = None
            for distribution in task_time_distribution:
                if distribution.personnel == task_person['personnel']:
                    matching_distribution = distribution
                    break

            # If matching Task Time Distribution is found, update the days_allocated and hours_allocated
            if matching_distribution:
                frappe.db.set_value('Task Time Distribution', matching_distribution.name, {
                    'days_allocated': task_person['days'],
                    'hours_allocated': task_person['hours']  # Update hours_allocated
                })
                frappe.log(f"Updated days_allocated & hours_allocated for Personnel {task_person['personnel']} in Task Time Distribution {matching_distribution.name}.")
            else:
                # Check if Task status is NOT Completed or Cancelled before creating new Task Time Distribution
                if doc.status not in ["Completed", "Cancelled"]:
                    new_task_time_distribution = frappe.get_doc({
                        'doctype': 'Task Time Distribution',
                        'project_task': doc.name,
                        'personnel': task_person['personnel'],
                        'days_allocated': task_person['days'],
                        'hours_allocated': task_person['hours']  # Include hours_allocated in new record
                    })
                    new_task_time_distribution.insert(ignore_permissions=True)
                    frappe.log(f"Created new Task Time Distribution for Personnel {task_person['personnel']} with {task_person['days']} days and {task_person['hours']} hours allocated.")
                else:
                    frappe.log(f"Task {doc.subject} is {doc.status}. Skipping creation of Task Time Distribution.")

        # Log completion of the update process
        frappe.log(f"Task Time Distribution records updated for Task {doc.subject}.")

    except Exception as e:
        # Log any errors for troubleshooting
        frappe.log_error(f"Error updating Task Time Distribution for Task: {doc.subject}. Error: {str(e)}", "Task Time Distribution Update Error")
else:
    # Default value if required fields are missing
    frappe.log("Subject is missing. Task Time Distribution update not performed.")

if not doc.project:
    pass  # Allow task creation if no project is linked
else:
    # Get Project Manager from Project Doctype
    project_manager = frappe.db.get_value("Project", doc.project, "custom_pm_name")

    if project_manager:
        # Get Personnel name from logged-in user's email
        personnel_name = frappe.db.get_value("Employee", {"user_id": frappe.session.user}, "employee_name")

        if personnel_name and personnel_name != project_manager:
            frappe.throw(f"Please contact the PM, {project_manager}, for Task creation in this Project")

#Auto Populate Title if empty

if not doc.custom_title:
    title = ""
    if doc.reference_type and doc.reference_name:
        try:
            ref_doc = frappe.get_doc(doc.reference_type, doc.reference_name)
            title = (
                getattr(ref_doc, "title", "")
                or getattr(ref_doc, "subject", "")
                or ref_doc.name
            )
            doc.custom_title = f"{doc.reference_type}: {title}"
        except:
            doc.custom_title = f"{doc.reference_type}: {doc.reference_name}"
    else:
        doc.custom_title = doc.description or "General Task"

# Purpose: replace the generic "Activity Type is mandatory" with a clearer message
# Context: Timesheet -> Time Logs (child: Timesheet Detail)
# FC-safe: no imports, no .format, no augmented assignments, no tuple-unpacking

project = doc.parent_project or ""
project_name = ""

# Try to fetch a friendly project name; fall back to the ID
if project:
    try:
        pn = frappe.db.get_value("Project", project, "project_name")
        project_name = pn or project
    except Exception:
        project_name = project

missing_rows = []
for row in (doc.time_logs or []):
    val = row.activity_type or ""
    if not val:
        idx_str = str(row.idx or "")
        missing_rows.append(idx_str)

if missing_rows:
    has_any_for_project = False
    if project:
        try:
            has_any_for_project = bool(frappe.db.exists("Activity Type", {"custom_project": project}))
        except Exception:
            has_any_for_project = False

    if has_any_for_project:
        detail = "Please pick a Project Rate Factor tied to project <b>" + project_name + "</b> or set a default."
    else:
        detail = "No Project Rate Factors are defined for project <b>" + project_name + "</b>. Please create one under the project."

    msg = "Row(s) " + ", ".join(missing_rows) + ": Project Rate Factor is missing.<br>" + detail
    frappe.throw(msg, title="Missing Project Rate Factor")
